DASHBOARD_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>Blockstone Capital · AI Trading Desk</title>\n    <style>\n        :root {\n            --bg-base: #060911;\n            --bg-card: #0e1526;\n            --bg-elevated: #162038;\n            --border: #1e2d4a;\n            --text-white: #ffffff;\n            --text-sub: #a0aec0;\n            --neon-green: #00ff9d;\n            --neon-red: #ff3b5c;\n            --neon-cyan: #00e5ff;\n            --neon-gold: #ffb703;\n            --neon-purple: #a855f7;\n        }\n\n        * {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n            -webkit-font-smoothing: antialiased;\n            -moz-osx-font-smoothing: grayscale;\n            text-rendering: geometricPrecision;\n        }\n\n        body {\n            background-color: var(--bg-base);\n            color: var(--text-white);\n            font-family: \'Segoe UI\', -apple-system, BlinkMacSystemFont, Roboto, sans-serif;\n            padding: 20px 24px;\n            min-height: 100vh;\n        }\n\n        /* Top Binance Live Strip */\n        .binance-strip {\n            background: #0d1527;\n            border: 2px solid #1e2e4f;\n            border-radius: 10px;\n            padding: 12px 22px;\n            margin-bottom: 20px;\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            font-size: 0.95rem;\n            font-weight: 700;\n            flex-wrap: wrap;\n            gap: 14px;\n        }\n\n        .ticker-group {\n            display: flex;\n            align-items: center;\n            gap: 24px;\n            flex-wrap: wrap;\n        }\n\n        .ticker-val {\n            font-size: 1.1rem;\n            font-weight: 800;\n        }\n\n        /* Header */\n        .header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            padding-bottom: 18px;\n            border-bottom: 2px solid var(--border);\n            margin-bottom: 22px;\n            flex-wrap: wrap;\n            gap: 16px;\n        }\n\n        .brand {\n            display: flex;\n            align-items: center;\n            gap: 14px;\n        }\n\n        .logo-icon {\n            width: 44px;\n            height: 44px;\n            border-radius: 10px;\n            background: linear-gradient(135deg, #00e5ff, #2563eb);\n            color: #ffffff;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            font-weight: 900;\n            font-size: 1.4rem;\n        }\n\n        .brand-text h1 {\n            font-size: 1.5rem;\n            font-weight: 800;\n            letter-spacing: -0.01em;\n        }\n\n        .brand-text p {\n            font-size: 0.88rem;\n            color: var(--text-sub);\n            font-weight: 600;\n        }\n\n        .header-actions {\n            display: flex;\n            align-items: center;\n            gap: 12px;\n            flex-wrap: wrap;\n        }\n\n        .autopilot-pill {\n            background: rgba(0, 255, 157, 0.15);\n            border: 2px solid var(--neon-green);\n            color: var(--neon-green);\n            padding: 8px 18px;\n            border-radius: 999px;\n            font-size: 0.9rem;\n            font-weight: 800;\n            display: inline-flex;\n            align-items: center;\n            gap: 10px;\n            cursor: pointer;\n            user-select: none;\n        }\n\n        .autopilot-pill.off {\n            background: rgba(160, 174, 192, 0.15);\n            border-color: var(--text-sub);\n            color: var(--text-sub);\n        }\n\n        .radar-dot {\n            width: 10px;\n            height: 10px;\n            border-radius: 50%;\n            background: var(--neon-green);\n            box-shadow: 0 0 12px var(--neon-green);\n        }\n\n        button {\n            cursor: pointer;\n            font-family: inherit;\n            font-weight: 800;\n            padding: 10px 18px;\n            border-radius: 8px;\n            border: none;\n            font-size: 0.9rem;\n            display: inline-flex;\n            align-items: center;\n            gap: 6px;\n            transition: transform 0.15s ease;\n        }\n        button:hover { transform: translateY(-1px); }\n\n        .btn-action {\n            background: var(--bg-elevated);\n            color: var(--text-white);\n            border: 2px solid var(--border);\n        }\n        .btn-action:hover {\n            border-color: var(--neon-cyan);\n            color: var(--neon-cyan);\n        }\n\n        .btn-kill {\n            background: rgba(255, 59, 92, 0.2);\n            color: var(--neon-red);\n            border: 2px solid var(--neon-red);\n        }\n        .btn-kill:hover { background: var(--neon-red); color: #fff; }\n\n        /* Large 5 KPI Grid */\n        .kpi-grid {\n            display: grid;\n            grid-template-columns: repeat(5, 1fr);\n            gap: 16px;\n            margin-bottom: 24px;\n        }\n\n        @media (max-width: 1300px) { .kpi-grid { grid-template-columns: repeat(3, 1fr); } }\n        @media (max-width: 768px) { .kpi-grid { grid-template-columns: repeat(1, 1fr); } }\n\n        .kpi-card {\n            background: var(--bg-card);\n            border: 2px solid var(--border);\n            border-radius: 12px;\n            padding: 20px;\n        }\n\n        .kpi-title {\n            color: var(--text-sub);\n            font-size: 0.82rem;\n            font-weight: 700;\n            text-transform: uppercase;\n            letter-spacing: 0.06em;\n            margin-bottom: 8px;\n        }\n\n        .kpi-val {\n            font-size: 2.1rem;\n            font-weight: 900;\n            font-family: \'Consolas\', \'Courier New\', monospace;\n            letter-spacing: -0.02em;\n        }\n\n        .kpi-sub {\n            font-size: 0.82rem;\n            color: var(--text-sub);\n            font-weight: 600;\n            margin-top: 6px;\n        }\n\n        /* Tables */\n        .positions-card {\n            background: #0b1220;\n            border: 2px solid #233558;\n            border-radius: 14px;\n            padding: 24px;\n            margin-bottom: 24px;\n            box-shadow: 0 4px 20px rgba(0, 0, 0, 0.4);\n        }\n\n        .positions-card .card-title {\n            font-size: 1.3rem;\n            font-weight: 900;\n            color: var(--text-white);\n            letter-spacing: -0.01em;\n        }\n\n        .positions-table {\n            width: 100%;\n            border-collapse: collapse;\n            font-size: 1rem;\n            margin-top: 8px;\n        }\n\n        .positions-table th {\n            text-align: left;\n            padding: 16px 14px;\n            color: #cbd5e1;\n            font-size: 0.88rem;\n            font-weight: 900;\n            text-transform: uppercase;\n            letter-spacing: 0.06em;\n            border-bottom: 2px solid #233558;\n            background: #111a2e;\n        }\n\n        .positions-table td {\n            padding: 18px 14px;\n            border-bottom: 1px solid #1e2d4a;\n            font-weight: 800;\n            font-family: \'Consolas\', \'Courier New\', monospace;\n            font-size: 1.05rem;\n            vertical-align: middle;\n            color: #ffffff;\n        }\n\n        .tag-long-lg {\n            background: rgba(0, 255, 157, 0.25);\n            color: #00ff9d;\n            border: 1.5px solid #00ff9d;\n            padding: 6px 14px;\n            border-radius: 6px;\n            font-weight: 900;\n            font-size: 0.9rem;\n            display: inline-block;\n        }\n\n        .tag-short-lg {\n            background: rgba(255, 59, 92, 0.25);\n            color: #ff3b5c;\n            border: 1.5px solid #ff3b5c;\n            padding: 6px 14px;\n            border-radius: 6px;\n            font-weight: 900;\n            font-size: 0.9rem;\n            display: inline-block;\n        }\n\n        .tag-lev-lg {\n            background: rgba(255, 183, 3, 0.25);\n            color: #ffb703;\n            border: 1.5px solid #ffb703;\n            padding: 6px 12px;\n            border-radius: 6px;\n            font-weight: 900;\n            font-size: 0.9rem;\n            display: inline-block;\n        }\n\n        .card-header {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 16px;\n            padding-bottom: 12px;\n            border-bottom: 2px solid var(--border);\n        }\n\n        .card-title {\n            font-size: 1.15rem;\n            font-weight: 800;\n            display: flex;\n            align-items: center;\n            gap: 10px;\n        }\n\n        .table {\n            width: 100%;\n            border-collapse: collapse;\n            font-size: 0.95rem;\n        }\n\n        .table th {\n            text-align: left;\n            padding: 14px;\n            color: var(--text-sub);\n            font-size: 0.82rem;\n            font-weight: 800;\n            text-transform: uppercase;\n            letter-spacing: 0.05em;\n            border-bottom: 2px solid var(--border);\n        }\n\n        .table td {\n            padding: 16px 14px;\n            border-bottom: 1px solid var(--border);\n            font-weight: 700;\n            font-family: \'Consolas\', \'Courier New\', monospace;\n            font-size: 0.95rem;\n            vertical-align: middle;\n        }\n\n        .tag-long {\n            background: rgba(0, 255, 157, 0.2);\n            color: var(--neon-green);\n            border: 1px solid var(--neon-green);\n            padding: 4px 10px;\n            border-radius: 6px;\n            font-weight: 900;\n            font-size: 0.85rem;\n        }\n\n        .tag-short {\n            background: rgba(255, 59, 92, 0.2);\n            color: var(--neon-red);\n            border: 1px solid var(--neon-red);\n            padding: 4px 10px;\n            border-radius: 6px;\n            font-weight: 900;\n            font-size: 0.85rem;\n        }\n\n        .tag-lev {\n            background: rgba(255, 183, 3, 0.2);\n            color: var(--neon-gold);\n            border: 1px solid var(--neon-gold);\n            padding: 4px 8px;\n            border-radius: 6px;\n            font-weight: 900;\n            font-size: 0.85rem;\n        }\n\n        .pnl-positive { color: var(--neon-green); font-weight: 900; font-size: 1.05rem; }\n        .pnl-negative { color: var(--neon-red); font-weight: 900; font-size: 1.05rem; }\n\n        .empty-state {\n            text-align: center;\n            padding: 32px;\n            color: var(--text-sub);\n            font-size: 0.95rem;\n            font-weight: 600;\n            font-style: italic;\n        }\n\n        /* Dual Column Layout */\n        .grid-2col {\n            display: grid;\n            grid-template-columns: 1.4fr 1fr;\n            gap: 20px;\n            margin-bottom: 24px;\n        }\n\n        @media (max-width: 1100px) { .grid-2col { grid-template-columns: 1fr; } }\n\n        .chart-container {\n            height: 350px;\n            border-radius: 10px;\n            overflow: hidden;\n            border: 2px solid var(--border);\n            background: #000;\n        }\n\n        .feed-container {\n            display: flex;\n            flex-direction: column;\n            gap: 12px;\n            max-height: 350px;\n            overflow-y: auto;\n        }\n\n        .signal-item {\n            background: var(--bg-elevated);\n            border: 1.5px solid var(--border);\n            border-radius: 8px;\n            padding: 14px;\n            border-left: 6px solid var(--neon-cyan);\n        }\n\n        .signal-item.up { border-left-color: var(--neon-green); }\n        .signal-item.down { border-left-color: var(--neon-red); }\n\n        .signal-top {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            margin-bottom: 6px;\n        }\n\n        .signal-agent { font-weight: 800; font-size: 0.95rem; color: var(--neon-cyan); }\n        .signal-evidence { font-size: 0.85rem; color: var(--text-sub); font-weight: 600; line-height: 1.4; }\n    </style>\n</head>\n<body>\n\n    <!-- Binance Live Market Ticker Strip -->\n    <div class="binance-strip">\n        <div class="ticker-group">\n            <div class="ticker-item">\n                <span style="color: var(--neon-gold);">🟡 BINANCE BTC/USDT:</span>\n                <span class="ticker-val" id="btcPrice" style="color: var(--neon-green);">$78,160.00</span>\n                <span id="btcChange" style="color: var(--neon-green);">+2.45%</span>\n            </div>\n            <div class="ticker-item">\n                <span style="color: var(--neon-gold);">🟡 BINANCE ETH/USDT:</span>\n                <span class="ticker-val" id="ethPrice">$3,520.00</span>\n            </div>\n        </div>\n        <div>\n            24h Futures Liqs: <span style="color: var(--neon-red); font-weight: 800;">$28.5M Longs</span> · <span style="color: var(--neon-green); font-weight: 800;">$14.2M Shorts</span>\n        </div>\n    </div>\n\n    <!-- Header -->\n    <div class="header">\n        <div class="brand">\n            <div class="logo-icon">BC</div>\n            <div class="brand-text">\n                <h1>Blockstone Capital</h1>\n                <p>15 Specialized Autonomous AI Agents · Head Trader Consensus Engine</p>\n            </div>\n        </div>\n\n        <div class="header-actions">\n            <div class="autopilot-pill" id="autopilotBtn" onclick="toggleAutopilot()">\n                <div class="radar-dot"></div>\n                <span id="autopilotText">AUTONOMOUS TRADING: ON</span>\n            </div>\n            <button class="btn-action" onclick="simulateOrder(\'BTC/USDT\', \'buy\')">⚡ Buy BTC (10x Lev)</button>\n            <button class="btn-action" onclick="simulateOrder(\'ETH/USDT\', \'sell\')">⚡ Short ETH (10x Lev)</button>\n            <button class="btn-kill" style="background: rgba(255, 183, 3, 0.2); color: var(--neon-gold); border-color: var(--neon-gold);" onclick="resetAllHistory()">🧹 Reset All History</button>\n            <button class="btn-kill" id="killBtn" onclick="toggleKillSwitch()">🛑 Kill-Switch</button>\n        </div>\n    </div>\n\n    <!-- 5 Large KPI Metric Cards -->\n    <div class="kpi-grid">\n        <div class="kpi-card">\n            <div class="kpi-title">Base Cash Balance</div>\n            <div class="kpi-val" id="kpiEquity" style="color: var(--neon-cyan);">$1,000.00</div>\n            <div class="kpi-sub">Starting Capital</div>\n        </div>\n\n        <div class="kpi-card" style="border-color: rgba(0, 255, 157, 0.5);">\n            <div class="kpi-title" style="color: var(--neon-green);">Live Market Value Portfolio</div>\n            <div class="kpi-val" id="kpiLiveMarketValue" style="color: var(--neon-green);">$1,000.00</div>\n            <div class="kpi-sub" id="kpiLivePnLSub">+$0.00 (+0.00%) Live Fluctuation</div>\n        </div>\n\n        <div class="kpi-card">\n            <div class="kpi-title">Active Market Exposure</div>\n            <div class="kpi-val" id="kpiExposure">$0.00</div>\n            <div class="kpi-sub">10x Leverage Purchasing Power</div>\n        </div>\n\n        <div class="kpi-card">\n            <div class="kpi-title">Active Positions</div>\n            <div class="kpi-val" id="kpiPositions" style="color: var(--neon-cyan);">0</div>\n            <div class="kpi-sub">Max 3 Trades</div>\n        </div>\n\n        <div class="kpi-card">\n            <div class="kpi-title">Drawdown / Limit</div>\n            <div class="kpi-val" id="kpiDrawdown">0.00%</div>\n            <div class="kpi-sub">Halt Threshold: 15%</div>\n        </div>\n    </div>\n\n    <!-- Live Running Positions Table (Large High-Contrast Font) -->\n    <div class="positions-card">\n        <div class="card-header">\n            <div class="card-title">💼 Live Running Positions · Real-Time Leverage & Liquidation Monitor</div>\n            <button class="btn-kill" style="padding: 8px 18px; font-size: 0.9rem; font-weight: 900;" onclick="closeAllPositions()">Close All Positions</button>\n        </div>\n        <table class="positions-table">\n            <thead>\n                <tr>\n                    <th>Symbol</th>\n                    <th>Side</th>\n                    <th>Leverage</th>\n                    <th>Margin</th>\n                    <th>Entry Price</th>\n                    <th>Mark Price</th>\n                    <th>Est. Liq Price</th>\n                    <th>Distance to Liq</th>\n                    <th>SL / TP</th>\n                    <th>Unrealized P&L</th>\n                    <th>Action</th>\n                </tr>\n            </thead>\n            <tbody id="positionsBody">\n                <tr>\n                    <td colspan="11" class="empty-state">No open positions. Autonomous Trader is scanning Binance futures for setups...</td>\n                </tr>\n            </tbody>\n        </table>\n    </div>\n\n    <!-- Closed Trades & Realized P&L Ledger (NEW) -->\n    <div class="card">\n        <div class="card-header">\n            <div class="card-title">📜 Closed Trades & Realized P&L History Log</div>\n            <span style="font-size: 0.85rem; color: var(--neon-green); font-weight: 800;">● PKT Local Time (12-Hour AM/PM)</span>\n        </div>\n        <table class="table">\n            <thead>\n                <tr>\n                    <th>CLOSED DATE & TIME (PKT)</th>\n                    <th>SYMBOL</th>\n                    <th>SIDE</th>\n                    <th>ENTRY PRICE</th>\n                    <th>EXIT PRICE</th>\n                    <th>SL / TP</th>\n                    <th>REALIZED P&L</th>\n                    <th>CLOSED BY / REASON</th>\n                </tr>\n            </thead>\n            <tbody id="closedTradesBody">\n                <tr>\n                    <td colspan="8" class="empty-state">No closed trades recorded yet. Close a position to view full entry, exit, SL/TP, and P&L history!</td>\n                </tr>\n            </tbody>\n        </table>\n    </div>\n\n    <!-- Dual Column: Chart + Signals -->\n    <div class="grid-2col">\n        <div class="card">\n            <div class="card-header">\n                <div class="card-title">📊 Live Binance Futures Market Chart</div>\n                <span style="font-size: 0.85rem; color: var(--neon-cyan); font-weight: 800;">BTC/USDT 15m</span>\n            </div>\n            <div class="chart-container">\n                <iframe src="https://s.tradingview.com/widgetembed/?frameElementId=tradingview_76b4a&symbol=BINANCE%3ABTCUSDT.P&interval=15&hidesidetoolbar=1&symboledit=1&saveimage=1&toolbarbg=060911&studies=%5B%5D&theme=dark&style=1&timezone=Etc%2FUTC&locale=en" width="100%" height="100%" frameborder="0" scrolling="no"></iframe>\n            </div>\n        </div>\n\n        <div class="card">\n            <div class="card-header">\n                <div class="card-title">📡 Real-Time AI Agent Signals Stream</div>\n                <span style="font-size: 0.85rem; color: var(--neon-green); font-weight: 800;">● Active Stream</span>\n            </div>\n            <div class="feed-container" id="signalFeed">\n                <div class="signal-item up">\n                    <div class="signal-top">\n                        <span class="signal-agent">TrendAgent (Technical)</span>\n                        <span class="tag-long">UP · 88% Conf</span>\n                    </div>\n                    <div class="signal-evidence">BTC/USDT: 4h EMA9 > EMA21 confirmed. Price above SMA200 ($76,400), ADX=34.2 (Strong Trend).</div>\n                </div>\n\n                <div class="signal-item up">\n                    <div class="signal-top">\n                        <span class="signal-agent">WhaleAgent (On-Chain)</span>\n                        <span class="tag-long">UP · 82% Conf</span>\n                    </div>\n                    <div class="signal-evidence">BTC/USDT: $24.8M withdrawn to cold storage custody wallets from Binance.</div>\n                </div>\n\n                <div class="signal-item down">\n                    <div class="signal-top">\n                        <span class="signal-agent">FundingAgent (Derivatives)</span>\n                        <span class="tag-short">DOWN · 65% Conf</span>\n                    </div>\n                    <div class="signal-evidence">ETH/USDT: Funding rate +0.045% indicates retail long overextension.</div>\n                </div>\n            </div>\n        </div>\n    </div>\n\n    <!-- OMS Execution History -->\n    <div class="card">\n        <div class="card-header">\n            <div class="card-title">📋 OMS Order Execution History</div>\n            <span style="font-size: 0.85rem; color: var(--text-sub); font-weight: 800;">● PKT Date & Time</span>\n        </div>\n        <table class="table">\n            <thead>\n                <tr>\n                    <th>DATE & TIME (PKT)</th>\n                    <th>ORDER ID</th>\n                    <th>SYMBOL</th>\n                    <th>SIDE</th>\n                    <th>QUANTITY</th>\n                    <th>NOTIONAL</th>\n                    <th>STATUS</th>\n                </tr>\n            </thead>\n            <tbody id="ordersBody">\n                <tr>\n                    <td colspan="7" class="empty-state">No order history yet.</td>\n                </tr>\n            </tbody>\n        </table>\n    </div>\n\n    <script>\n        let autopilotActive = true;\n        let lastPositionsHash = "";\n        let lastOrdersHash = "";\n        let lastClosedHash = "";\n\n        async function fetchDashboard() {\n            try {\n                // 1. Fetch portfolio & positions\n                const res = await fetch(\'/api/dashboard/\');\n                if (res.ok) {\n                    const data = await res.json();\n                    \n                    const equity = data.equity || 1000.0;\n                    const liveMarketValue = data.live_market_value_portfolio || equity;\n                    const totalPnl = data.total_unrealized_pnl || 0.0;\n                    const livePnlPct = data.live_pnl_pct || 0.0;\n\n                    document.getElementById(\'kpiEquity\').innerText = \'$\' + equity.toLocaleString(\'en-US\', {minimumFractionDigits: 2});\n                    \n                    const liveValElem = document.getElementById(\'kpiLiveMarketValue\');\n                    const subPnlElem = document.getElementById(\'kpiLivePnLSub\');\n                    liveValElem.innerText = \'$\' + liveMarketValue.toLocaleString(\'en-US\', {minimumFractionDigits: 2});\n                    liveValElem.style.color = totalPnl >= 0 ? \'var(--neon-green)\' : \'var(--neon-red)\';\n                    \n                    subPnlElem.innerText = `${totalPnl >= 0 ? \'+\' : \'\'}$${totalPnl.toFixed(2)} (${livePnlPct >= 0 ? \'+\' : \'\'}${livePnlPct.toFixed(2)}%) Live PnL`;\n                    subPnlElem.style.color = totalPnl >= 0 ? \'var(--neon-green)\' : \'var(--neon-red)\';\n\n                    document.getElementById(\'kpiExposure\').innerText = \'$\' + (data.total_exposure || 0.0).toLocaleString(\'en-US\', {minimumFractionDigits: 2});\n                    document.getElementById(\'kpiDrawdown\').innerHTML = (data.drawdown_pct || 0).toFixed(2) + \'% <span style="font-size: 0.82rem; color: var(--text-sub);">/ 15%</span>\';\n                    document.getElementById(\'kpiPositions\').innerText = data.positions_count || 0;\n\n                    const newPosHash = JSON.stringify(data.positions);\n                    if (newPosHash !== lastPositionsHash) {\n                        lastPositionsHash = newPosHash;\n                        const posBody = document.getElementById(\'positionsBody\');\n                        if (data.positions && data.positions.length > 0) {\n                            posBody.innerHTML = data.positions.map(p => `\n                                <tr>\n                                    <td><b style="font-size: 1.15rem; color: #ffffff;">${p.symbol}</b></td>\n                                    <td><span class="${p.side === \'LONG\' ? \'tag-long-lg\' : \'tag-short-lg\'}">${p.side}</span></td>\n                                    <td><span class="tag-lev-lg">${p.leverage}</span></td>\n                                    <td style="color: #ffffff; font-weight: 800;">${p.margin_used}</td>\n                                    <td style="color: #ffffff;">$${p.entry_price.toLocaleString(\'en-US\', {minimumFractionDigits: 2})}</td>\n                                    <td style="color: #ffffff; font-weight: 900;">$${p.current_price.toLocaleString(\'en-US\', {minimumFractionDigits: 2})}</td>\n                                    <td style="color: var(--neon-red); font-weight: 900; font-size: 1.1rem;">$${p.liq_price.toLocaleString(\'en-US\', {minimumFractionDigits: 2})}</td>\n                                    <td style="color: var(--neon-cyan); font-weight: 900;">${p.distance_to_liq}</td>\n                                    <td style="color: #cbd5e1; font-size: 0.92rem;">$${p.stop_loss} / $${p.take_profit}</td>\n                                    <td class="${p.unrealized_pnl >= 0 ? \'pnl-positive\' : \'pnl-negative\'}" style="font-size: 1.15rem;">\n                                        ${p.unrealized_pnl >= 0 ? \'+\' : \'\'}$${p.unrealized_pnl.toFixed(2)} (${p.pnl_pct >= 0 ? \'+\' : \'\'}${p.pnl_pct.toFixed(1)}%)\n                                    </td>\n                                    <td><button class="btn-kill" style="padding: 6px 16px; font-size: 0.85rem; font-weight: 900;" onclick="closeAllPositions()">Close</button></td>\n                                </tr>\n                            `).join("");\n                        } else {\n                            posBody.innerHTML = `<tr><td colspan="11" class="empty-state">No open positions. Autonomous Trader is scanning for setups...</td></tr>`;\n                        }\n                    }\n                }\n\n                // 2. Fetch Closed Trades History\n                const closedRes = await fetch(\'/api/trades/closed\');\n                if (closedRes.ok) {\n                    const closedTrades = await closedRes.json();\n                    const newClosedHash = JSON.stringify(closedTrades);\n                    if (newClosedHash !== lastClosedHash) {\n                        lastClosedHash = newClosedHash;\n                        const closedBody = document.getElementById(\'closedTradesBody\');\n                        if (closedTrades && closedTrades.length > 0) {\n                            closedBody.innerHTML = closedTrades.map(c => `\n                                <tr>\n                                    <td style="color: var(--text-white); font-weight: 700;">${c.closed_at}</td>\n                                    <td><b style="font-size: 1.05rem;">${c.symbol}</b></td>\n                                    <td><span class="${c.side === \'LONG\' ? \'tag-long\' : \'tag-short\'}">${c.side}</span></td>\n                                    <td>$${c.entry_price.toLocaleString(\'en-US\', {minimumFractionDigits: 2})}</td>\n                                    <td>$${c.exit_price.toLocaleString(\'en-US\', {minimumFractionDigits: 2})}</td>\n                                    <td style="color: var(--text-sub); font-size: 0.85rem;">${c.sl_tp}</td>\n                                    <td class="${c.realized_pnl >= 0 ? \'pnl-positive\' : \'pnl-negative\'}">\n                                        ${c.realized_pnl >= 0 ? \'+\' : \'\'}$${c.realized_pnl.toFixed(2)} (${c.pnl_pct >= 0 ? \'+\' : \'\'}${c.pnl_pct.toFixed(1)}%)\n                                    </td>\n                                    <td><span style="color: var(--neon-cyan); font-weight: 800;">${c.closed_by}</span></td>\n                                </tr>\n                            `).join("");\n                        } else {\n                            closedBody.innerHTML = `<tr><td colspan="8" class="empty-state">No closed trades recorded yet. Close a position to view full entry, exit, SL/TP, and P&L history!</td></tr>`;\n                        }\n                    }\n                }\n\n                // 3. Fetch OMS Orders History\n                const tradesRes = await fetch(\'/api/trades/\');\n                if (tradesRes.ok) {\n                    const orders = await tradesRes.json();\n                    const newOrdHash = JSON.stringify(orders);\n                    if (newOrdHash !== lastOrdersHash) {\n                        lastOrdersHash = newOrdHash;\n                        const ordersBody = document.getElementById(\'ordersBody\');\n                        if (orders && orders.length > 0) {\n                            ordersBody.innerHTML = orders.map(o => `\n                                <tr>\n                                    <td style="color: var(--text-white); font-weight: 700;">${o.created_at}</td>\n                                    <td><code>${o.order_id}</code></td>\n                                    <td><b style="font-size: 1.05rem;">${o.symbol}</b></td>\n                                    <td><span class="${o.side === \'BUY\' ? \'tag-long\' : \'tag-short\'}">${o.side}</span></td>\n                                    <td>${o.quantity}</td>\n                                    <td>$${o.notional}</td>\n                                    <td><span style="color: var(--neon-green); font-weight: 900;">${o.status}</span></td>\n                                </tr>\n                            `).join("");\n                        }\n                    }\n                }\n\n                // 4. Fetch Binance Tickers\n                const btcRes = await fetch(\'/api/binance/ticker?symbol=BTC/USDT\');\n                if (btcRes.ok) {\n                    const t = await btcRes.json();\n                    if (t.last) {\n                        document.getElementById(\'btcPrice\').innerText = \'$\' + t.last.toLocaleString(\'en-US\', {minimumFractionDigits: 2});\n                        const chg = t.change24h_pct || 0;\n                        document.getElementById(\'btcChange\').innerText = (chg >= 0 ? \'+\' : \'\') + chg.toFixed(2) + \'%\';\n                        document.getElementById(\'btcChange\').style.color = chg >= 0 ? \'var(--neon-green)\' : \'var(--neon-red)\';\n                    }\n                }\n\n                const ethRes = await fetch(\'/api/binance/ticker?symbol=ETH/USDT\');\n                if (ethRes.ok) {\n                    const t2 = await ethRes.json();\n                    if (t2.last) {\n                        document.getElementById(\'ethPrice\').innerText = \'$\' + t2.last.toLocaleString(\'en-US\', {minimumFractionDigits: 2});\n                    }\n                }\n            } catch (e) {\n                console.error("Dashboard poll error:", e);\n            }\n        }\n\n        async function toggleAutopilot() {\n            const res = await fetch(\'/api/control/autopilot/toggle\', { method: \'POST\' });\n            if (res.ok) {\n                const d = await res.json();\n                autopilotActive = d.autopilot_active;\n                const pill = document.getElementById(\'autopilotBtn\');\n                const txt = document.getElementById(\'autopilotText\');\n                if (autopilotActive) {\n                    pill.className = \'autopilot-pill\';\n                    txt.innerText = \'AUTONOMOUS TRADING: ON\';\n                } else {\n                    pill.className = \'autopilot-pill off\';\n                    txt.innerText = \'AUTONOMOUS TRADING: PAUSED\';\n                }\n            }\n        }\n\n        async function simulateOrder(symbol, side) {\n            try {\n                const res = await fetch(`/api/trades/simulate?symbol=${encodeURIComponent(symbol)}&side=${side}`, {\n                    method: \'POST\'\n                });\n                if (res.ok) {\n                    const d = await res.json();\n                    const feed = document.getElementById(\'signalFeed\');\n                    const div = document.createElement(\'div\');\n                    div.className = \'signal-item \' + (side === \'buy\' ? \'up\' : \'down\');\n                    div.innerHTML = `\n                        <div class="signal-top">\n                            <span class="signal-agent">Head Trader AI Consensus</span>\n                            <span class="${side === \'buy\' ? \'tag-long\' : \'tag-short\'}">${side.toUpperCase()} ${symbol} · 89% Conf</span>\n                        </div>\n                        <div class="signal-evidence">Order executed at $${d.live_price ? d.live_price.toLocaleString() : \'market\'}. Hard risk limits satisfied.</div>\n                    `;\n                    feed.insertBefore(div, feed.firstChild);\n                    lastPositionsHash = "";\n                    fetchDashboard();\n                }\n            } catch (e) {\n                alert("Error: " + e);\n            }\n        }\n\n        async function closeAllPositions() {\n            await fetch(\'/api/trades/close-all\', { method: \'POST\' });\n            lastPositionsHash = "";\n            lastClosedHash = "";\n            fetchDashboard();\n        }\n\n        async function resetAllHistory() {\n            if (confirm("Are you sure you want to clear all previous trades & history and reset balance to $1,000.00 USDT?")) {\n                await fetch(\'/api/trades/reset-all\', { method: \'POST\' });\n                lastPositionsHash = "";\n                lastOrdersHash = "";\n                lastClosedHash = "";\n                fetchDashboard();\n            }\n        }\n\n        async function toggleKillSwitch() {\n            const btn = document.getElementById(\'killBtn\');\n            const res = await fetch(\'/api/control/kill-switch/activate\', { method: \'POST\' });\n            if (res.ok) {\n                alert("🛑 EMERGENCY KILL-SWITCH ACTIVATED! All auto-trading paused.");\n                btn.style.background = "var(--neon-red)";\n                btn.style.color = "#fff";\n                btn.innerText = "KILL-SWITCH ENGAGED";\n            }\n        }\n\n        setInterval(fetchDashboard, 2500);\n        fetchDashboard();\n    </script>\n</body>\n</html>\n'
